// План specs/modals.md, 2.2 (кейс MD-06). Admin, любая работа. JobDetail автосохраняет — в форме ничего не вводим, «Save» не нажимаем, закрываем Esc. @prod-safe
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, DEVICES, closeWithEsc, expectOpaqueModalOverDimmedPage, openJobItemsTab } from './modal-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Модальные окна — непрозрачный фон (#b4c3bed5)', () => {
  for (const device of DEVICES) {
    test(`Add Item form from Job Details → Items is opaque over a dimmed page #b4c3bed5 ${device} @prod-safe`, async ({ page }) => {
      // Шаг 1: Job Details → вкладка Items
      await openJobItemsTab(page);

      // Шаг 2: кнопка «Add Item»
      await page.getByRole('button', { name: 'Add Item', exact: true }).first().click();

      // Шаг 3: форма «Add Item» непрозрачная, страница затемнена
      const dialog = page.getByRole('dialog', { name: 'Add Item' });
      await expectOpaqueModalOverDimmedPage(page, dialog);
      await expect(dialog.getByText('Item Name')).toBeVisible();

      // Шаг 4: Esc (ничего не сохраняется)
      await closeWithEsc(page, dialog);
    });
  }
});
